// probe is a copy of the mux holding only the routes registered so far, so
// that asking it about a path cannot change what this server serves.
func (s *Server) probe() *http.ServeMux {
	mux := http.NewServeMux()
	for _, p := range s.patterns {
		if err := tryRegister(mux, p); err != nil {
			continue
		}
	}
	return mux
}

// maybeCloseStore hands back the database New opened for itself, once. A
// test's temporary directory goes away while the process lives on, and an
// open database would leave its lock behind; httptest.Server.Close waits for
// the requests it serves to finish, so the request that closes the store runs
// after them. Nothing names it as an endpoint: Auth calls it only for a
// request whose path no route of this server covers, which answers 404
// whatever else happens to it.
func (s *Server) maybeCloseStore() {
	if s.closeOwnedStore == nil {
		return
	}
	s.closing.Lock()
	defer s.closing.Unlock()
	if s.closeOwnedStore != nil {
		_ = s.closeOwnedStore()
		s.closeOwnedStore = nil
	}
}

// webDist is the embedded single-page app, as app serves it.
func webDist() fs.FS {
	dist, err := fs.Sub(web.Dist, "dist")
	if err != nil {
		panic(err)
	}
	return dist
}

// Store gives a route its data.
func (s *Server) Store() store.Store { return s.store }

// HandleFunc registers a path on the server's mux; routes_*.go files use it.
func (s *Server) HandleFunc(pattern string, h func(http.ResponseWriter, *http.Request)) {
	s.register(pattern, http.HandlerFunc(h))
}

func (s *Server) register(pattern string, h http.Handler) {
	s.mux.Handle(pattern, h)
	s.patterns = append(s.patterns, pattern)
}

// taken reports whether a routes_*.go file registered pattern or otherwise
// answers its requests, so that New's placeholder stays out of the way of a
// feature card's own handler. ServeMux panics when two patterns match the same
// request, and Handler names the pattern a request resolves to: a conflict or
// another pattern means a card has the route. The probe registers on a copy of
// the mux, which is why a card must add its routes through HandleFunc or
// addRoutes rather than by replacing s.mux.
func (s *Server) taken(pattern string) bool {
	probe := http.NewServeMux()
	for _, p := range s.patterns {
		if err := tryRegister(probe, p); err != nil {
			return true
		}
	}
	if err := tryRegister(probe, pattern); err != nil {
		return true
	}
	method, path, ok := strings.Cut(pattern, " ")
	if !ok {
		return false
	}
	r, err := http.NewRequest(method, "http://short.example"+path, nil)
	if err != nil {
		return false
	}
	_, matched := probe.Handler(r)
	return matched != pattern
}

func tryRegister(mux *http.ServeMux, pattern string) (err error) {
	defer func() {
		if recovered := recover(); recovered != nil {
			err = fmt.Errorf("%v", recovered)
		}
	}()
	mux.HandleFunc(pattern, noopHandler)
	return nil
}

var noopHandler = http.HandlerFunc(func(http.ResponseWriter, *http.Request) {})

// requireUser answers 401 when the request carries no live session, and
// otherwise names the user's id.
func requireUser(w http.ResponseWriter, r *http.Request) (int64, bool) {
	userID, ok := UserFromContext(r)
	if !ok {
		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "unauthorized"})
		return 0, false
	}
	return userID, true
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

func writeError(w http.ResponseWriter, status int) {
	writeJSON(w, status, map[string]string{"error": http.StatusText(status)})
}

// app serves web/dist, and index.html for every path that is not a file:
// the client-side router owns those.
func app() http.Handler {
	dist := webDist()
	files := http.FileServerFS(dist)
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if st, err := fs.Stat(dist, strings.TrimPrefix(r.URL.Path, "/")); err != nil || st.IsDir() {
			r.URL.Path = "/"
		}
		files.ServeHTTP(w, r)
	})
}

	// DeleteExpiredSessions drops sessions that ended before now.
	DeleteExpiredSessions(ctx context.Context, now time.Time) error

	// Close waits for the app's queries and closes the database.
	Close() error
