func (s *SQLiteStore) GetClickStats(ctx context.Context, slug string, now time.Time, days int) (*LinkStats, error) {
	link, err := s.GetLinkBySlug(ctx, slug)
	if err != nil {
		return nil, err
	}
	if days < 1 {
		days = 1
	}
	start := time.Date(now.UTC().Year(), now.UTC().Month(), now.UTC().Day(), 0, 0, 0, 0, time.UTC).
		AddDate(0, 0, -(days - 1))

	rows, err := s.db.QueryContext(ctx,
		`SELECT day, count FROM clicks WHERE link_id = ? AND day >= ? AND day <= ?`,
		link.ID, day(start), day(now))
	if err != nil {
		return nil, err
	}
	defer func() { _ = rows.Close() }()
	counts := map[string]int64{}
	for rows.Next() {
		var d string
		var n int64
		if err := rows.Scan(&d, &n); err != nil {
			return nil, err
		}
		counts[d] = n
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	stats := &LinkStats{Slug: link.Slug, TotalClicks: link.TotalClicks, Days: make([]DayClicks, 0, days)}
	for i := 0; i < days; i++ {
		d := day(start.AddDate(0, 0, i))
		stats.Days = append(stats.Days, DayClicks{Date: d, Clicks: counts[d]})
	}
	return stats, nil
}

