func TestNewOpensStoreAndServes(t *testing.T) {
	dir := filepath.Join(t.TempDir(), "data")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	srv := httptest.NewServer(New(Config{DataDir: dir}))

	res, err := srv.Client().Get(srv.URL + "/healthz")
	if err != nil {
		t.Fatal(err)
	}
	_ = res.Body.Close()
	if res.StatusCode != http.StatusOK {
		t.Fatalf("healthz: %d", res.StatusCode)
	}
	if _, err := os.Stat(filepath.Join(dir, "links.db")); err != nil {
		t.Fatalf("New opened no database: %v", err)
	}

	tests := []struct {
		path   string
		method string
		want   int
	}{
		{"/api/me", http.MethodGet, http.StatusUnauthorized},
		{"/api/nothing-here", http.MethodGet, http.StatusNotFound},
		// POST /api/links is the links card's route: with no session it answers
		// 401, not the 404 a path no route names gives.
		// An unknown path under / answers 404 and is where New hands back the
		// store it opened for itself; there is no /shutdown endpoint.
		{"/nope123", http.MethodGet, http.StatusNotFound},
	}
	for _, c := range tests {
		req, err := http.NewRequest(c.method, srv.URL+c.path, nil)
		if err != nil {
			t.Fatal(err)
		}
		res, err := srv.Client().Do(req)
		if err != nil {
			t.Fatal(err)
		}
		_ = res.Body.Close()
		if res.StatusCode != c.want {
			t.Errorf("%s %s: %d, want %d", c.method, c.path, res.StatusCode, c.want)
		}
	}
	srv.Close()
	if open := openSQLiteFiles(t, dir); open > 0 {
		t.Errorf("after the handler went out of use, %d of the database's side files are still there", open)
	}
}

