package server

import (
	"encoding/json"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

// authServer serves the app over a database of its own and never shares the
// rate-limit map with another test: resetAuthRate clears it.
func authServer(t *testing.T) *httptest.Server {
	t.Helper()
	resetAuthRate()
	srv := httptest.NewServer(New(Config{DataDir: t.TempDir()}))
	t.Cleanup(srv.Close)
	return srv
}

func postJSON(t *testing.T, srv *httptest.Server, path, body string) *http.Response {
	t.Helper()
	req, err := http.NewRequest(http.MethodPost, srv.URL+path, strings.NewReader(body))
	if err != nil {
		t.Fatal(err)
	}
	req.Header.Set("Content-Type", "application/json")
	res, err := srv.Client().Do(req)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = res.Body.Close() })
	return res
}

func cookieOf(t *testing.T, res *http.Response) *http.Cookie {
	t.Helper()
	for _, c := range res.Cookies() {
		if c.Name == SessionCookie {
			return c
		}
	}
	t.Fatalf("%s %d sets no %s cookie", res.Request.URL.Path, res.StatusCode, SessionCookie)
	return nil
}

func getMe(t *testing.T, srv *httptest.Server, token string) (*http.Response, userJSON) {
	t.Helper()
	req, err := http.NewRequest(http.MethodGet, srv.URL+"/api/me", nil)
	if err != nil {
		t.Fatal(err)
	}
	if token != "" {
		req.Header.Set("Cookie", SessionCookie+"="+token)
	}
	res, err := srv.Client().Do(req)
	if err != nil {
		t.Fatal(err)
	}
	defer func() { _ = res.Body.Close() }()
	var user userJSON
	body, _ := io.ReadAll(res.Body)
	if len(body) > 0 {
		if err := json.Unmarshal(body, &user); err != nil {
			t.Fatalf("GET /api/me: %d body %q is no user JSON: %v", res.StatusCode, body, err)
		}
	}
	return res, user
}

