func (s *Server) signup(w http.ResponseWriter, r *http.Request) {
	if !authRate.allow(clientIP(r), time.Now()) {
		writeError(w, http.StatusTooManyRequests)
		return
	}
	creds, ok := decodeCredentials(w, r)
	if !ok {
		return
	}
	email := strings.ToLower(strings.TrimSpace(creds.Email))
	if !validEmail(email) {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid email"})
		return
	}
	if len(creds.Password) < minPasswordLen {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "password too short"})
		return
	}
	hash, err := bcrypt.GenerateFromPassword([]byte(creds.Password), bcrypt.DefaultCost)
	if err != nil {
		writeError(w, http.StatusInternalServerError)
		return
	}
	user := &store.User{Email: email, PasswordHash: string(hash), CreatedAt: time.Now().UTC()}
	if err := s.store.CreateUser(r.Context(), user); err != nil {
		if errors.Is(err, store.ErrDuplicate) {
			writeError(w, http.StatusConflict)
			return
		}
		writeError(w, http.StatusInternalServerError)
		return
	}
	s.startSession(w, r, user)
}

func (s *Server) login(w http.ResponseWriter, r *http.Request) {
	key := clientIP(r)
	if !authRate.allow(key, time.Now()) {
		writeError(w, http.StatusTooManyRequests)
		return
	}
	creds, ok := decodeCredentials(w, r)
	if !ok {
		return
	}
	email := strings.ToLower(strings.TrimSpace(creds.Email))
	user, err := s.store.GetUserByEmail(r.Context(), email)
	if err != nil {
		if errors.Is(err, store.ErrNotFound) {
			writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "invalid credentials"})
			return
		}
		writeError(w, http.StatusInternalServerError)
		return
	}
	if bcrypt.CompareHashAndPassword([]byte(user.PasswordHash), []byte(creds.Password)) != nil {
		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "invalid credentials"})
		return
	}
	authRate.reset(key)
	s.startSession(w, r, user)
}

// startSession issues the login cookie and answers the user's JSON, which the
// store read names: the hash never leaves it.
func (s *Server) startSession(w http.ResponseWriter, r *http.Request, user *store.User) {
	token, err := newSessionToken()
	if err != nil {
		writeError(w, http.StatusInternalServerError)
		return
	}
	now := time.Now().UTC()
	expires := now.Add(sessionTTL)
	if err := s.store.CreateSession(r.Context(), &store.Session{Token: token, UserID: user.ID, ExpiresAt: expires}); err != nil {
		writeError(w, http.StatusInternalServerError)
		return
	}
	http.SetCookie(w, sessionCookie(token, expires, requestSecure(r)))
	writeJSON(w, http.StatusOK, userOf(user))
}

func (s *Server) logout(w http.ResponseWriter, r *http.Request) {
	if c, err := r.Cookie(SessionCookie); err == nil && validSessionToken(c.Value) {
		if err := s.store.DeleteSession(r.Context(), c.Value); err != nil {
			writeError(w, http.StatusInternalServerError)
			return
		}
	}
	http.SetCookie(w, clearSessionCookie(requestSecure(r)))
	w.WriteHeader(http.StatusNoContent)
}

func (s *Server) me(w http.ResponseWriter, r *http.Request) {
	userID, ok := requireUser(w, r)
	if !ok {
		return
	}
	user, err := s.store.GetUserByID(r.Context(), userID)
	if err != nil {
		if errors.Is(err, store.ErrNotFound) {
			writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "unauthorized"})
			return
		}
		writeError(w, http.StatusInternalServerError)
		return
	}
	writeJSON(w, http.StatusOK, userOf(user))
}

// newSessionToken is 32 random bytes, base64url without padding: 43
// characters, which validSessionToken accepts.
func newSessionToken() (string, error) {
	var b [32]byte
	if _, err := rand.Read(b[:]); err != nil {
		return "", fmt.Errorf("server: session token: %w", err)
	}
	return base64.RawURLEncoding.EncodeToString(b[:]), nil
}

