// signup makes an account with a bcrypt hash of a password and returns a
// session token for it: this card's tests are about links, so they log in
// through the store rather than POST /api/signup, which is the auth card's.
func signup(t *testing.T, st store.Store, email string) string {
	t.Helper()
	hash, err := bcrypt.GenerateFromPassword([]byte("a passphrase of ten"), bcrypt.DefaultCost)
	if err != nil {
		t.Fatal(err)
	}
	u := &store.User{Email: email, PasswordHash: string(hash), CreatedAt: time.Now().UTC()}
	if err := st.CreateUser(context.Background(), u); err != nil {
		t.Fatal(err)
	}
	token := sessionToken(t, u.ID)
	sess := &store.Session{Token: token, UserID: u.ID, ExpiresAt: time.Now().Add(time.Hour)}
	if err := st.CreateSession(context.Background(), sess); err != nil {
		t.Fatal(err)
	}
	return token
}

// sessionToken is a random token of the shape Auth accepts: 43 base64url
// characters, as a real login would issue.
func sessionToken(t *testing.T, userID int64) string {
	t.Helper()
	buf := make([]byte, 32)
	if _, err := rand.Read(buf); err != nil {
		t.Fatal(err)
	}
	return base64.RawURLEncoding.EncodeToString(buf)
}

// clicks counts n redirects of a slug, as the redirect card's own tests will.
func clicks(t *testing.T, st store.Store, slug string, n int) {
	t.Helper()
	for i := 0; i < n; i++ {
		if err := st.IncrementClick(context.Background(), slug, time.Now()); err != nil {
			t.Fatal(err)
		}
	}
}

